from pathlib import Path
import hashlib, json, os, re, subprocess, shutil, textwrap, sys, time
root = Path(__file__).resolve().parents[1]
if str(root) not in sys.path:
    sys.path.insert(0, str(root))
from tools.architecture_governance import host_activity_stub_bounds
_host_stub_bounds = host_activity_stub_bounds(root)
if _host_stub_bounds['errors']:
    raise SystemExit('HOST_ACTIVITY_STUB_BOUNDS:' + ';'.join(_host_stub_bounds['errors']))
if hasattr(sys.stdout, 'reconfigure'):
    sys.stdout.reconfigure(encoding='utf-8', errors='replace')
if hasattr(sys.stderr, 'reconfigure'):
    sys.stderr.reconfigure(encoding='utf-8', errors='replace')
build = root / 'build' / 'static-android-compile'
stubs = build / 'stubs'
classes = build / 'classes'
shutil.rmtree(build, ignore_errors=True)
stubs.mkdir(parents=True)
classes.mkdir(parents=True)

def w(rel, text):
    p=stubs/rel; p.parent.mkdir(parents=True, exist_ok=True); p.write_text(
        textwrap.dedent(text).lstrip(), encoding='utf-8')

# Keep the generated Intent stub declaration below readable even when its
# long one-line body is patched independently.
W = w

def decode_process_output(value):
    if isinstance(value, str):
        return value
    for encoding in ('utf-8', 'gbk'):
        try:
            return value.decode(encoding)
        except UnicodeDecodeError:
            pass
    return value.decode('utf-8', errors='replace')

